#include <vector>
#include <iterator>
#include <algorithm>

template <class Iterator1, class Iterator2>
bool operator>(const std::reverse_iterator<Iterator1>& x, const std::reverse_iterator<Iterator2>& y) {
    return x.base() < y.base();
}

int main() {
    std::vector<int> v1 = {1, 2, 3};
    std::vector<int> v2 = {4, 5, 6};
    auto rit1 = v1.rbegin();
    auto rit2 = v2.rbegin();
    bool result = operator>(rit1, rit2);
    return 0;
}
